1: "use client";
2: 
3: import { useState, useCallback, useMemo } from "react";
4: import { toast } from "sonner";
5: import { Sheet, SheetContent, SheetHeader, SheetTitle } from "@/components/ui/sheet";
6: import Link from "next/link";
7: import { User, Sparkles, Gift } from "lucide-react";
8: import { Button } from "@/components/ui/button";
9: 
10: import { CalendarioSelector } from "./CalendarioSelector";
11: import { QuadraHorarioItem } from "./QuadraHorarioItem";
12: import { CarrinhoLateral, BotaoCarrinhoMobile } from "./CarrinhoLateral";
13: import { FormularioIdentificacao, type DadosIdentificacao } from "./FormularioIdentificacao";
14: import { ModalPix } from "./ModalPix";
15: import { ModalPosReservaCadastro } from "./ModalPosReservaCadastro";
16: import { MuralVagasAbertas } from "@/components/vagas/MuralVagasAbertas";
17: 
18: import { useReservasService } from "@/hooks/useReservasService";
19: import { useContratosService } from "@/hooks/useContratosService";
20: import { useUserAuth } from "@/hooks/useUserAuth";
21: import { useFidelidadeService } from "@/hooks/useFidelidadeService";
22: import type { VoucherFidelidade } from "@/lib/fidelidade/types";
23: import { aplicarDescontoVouchers } from "@/lib/fidelidade/fidelidadeService";
24: import { isTelefoneBloqueado } from "@/lib/supabase/authService";
25: import {
26:   gerarDiasDisponiveis,
27:   getHoje,
28:   calcularValorTotal,
29:   calcularValorSinal,
30:   calcularValorPendente,
31:   saoConsecutivos,
32:   isHorarioExpirado,
33: } from "@/lib/constants";
34: import { QUADRAS } from "@/lib/quadras";
35: 
36: type Etapa = "formulario" | "pix";
37: 
38: export function PortalCliente() {
39:   // ── Estado de seleção ──────────────────────────────────────────────────
40:   const dias = useMemo(() => gerarDiasDisponiveis(), []);
41:   const [dataSelecionada, setDataSelecionada] = useState<string>(getHoje());
42:   const [quadraSelecionada, setQuadraSelecionada] = useState<string | null>(null);
43:   const [horariosSelecionados, setHorariosSelecionados] = useState<string[]>([]);
44: 
45:   // ── Checkout ────────────────────────────────────────────────────────────
46:   const [etapa, setEtapa] = useState<Etapa | null>(null);
47:   const [reservaIdAtual, setReservaIdAtual] = useState<string | null>(null);
48:   const [dadosForm, setDadosForm] = useState<DadosIdentificacao | null>(null);
49:   const [tipoPagamentoEscolhido, setTipoPagamentoEscolhido] = useState<"sinal" | "integral">("sinal");
50:   const [isCarrinhoOpen, setIsCarrinhoOpen] = useState(false);
51:   const [vouchersSelecionadosIds, setVouchersSelecionadosIds] = useState<string[]>([]);
52: 
53:   // ── Autenticação de Usuário & Fidelidade ──────────────────────────────────
54:   const { user, isAutenticado } = useUserAuth();
55:   const { progresso, consumirVouchersNoCheckout } = useFidelidadeService();
56:   const [mostrarModalPosCadastro, setMostrarModalPosCadastro] = useState(false);
57:   const [dadosUltimaReserva, setDadosUltimaReserva] = useState<{
58:     id: string;
59:     nome: string;
60:     whatsapp: string;
61:   } | null>(null);
62: 
63:   // ── Service ─────────────────────────────────────────────────────────────
64:   const {
65:     getHorariosOcupados,
66:     criarReservaEmProcessamento,
67:     atualizarIdentificacao,
68:     atualizarDadosCheckout,
69:     confirmarPagamento,
70:     liberarLock,
71:   } = useReservasService();
72:   const { getAvisosEscolinha } = useContratosService();
73: 
74:   // ── Valores calculados ──────────────────────────────────────────────────
75:   const valorTotalBruto = useMemo(
76:     () => calcularValorTotal(horariosSelecionados),
77:     [horariosSelecionados]
78:   );
79: 
80:   const vouchersAtivosParaReserva = useMemo(() => {
81:     return progresso.vouchersDisponiveis.filter((v) =>
82:       vouchersSelecionadosIds.includes(v.id)
83:     );
84:   }, [vouchersSelecionadosIds, progresso.vouchersDisponiveis]);
85: 
86:   const resultadoDesconto = useMemo(
87:     () =>
88:       vouchersAtivosParaReserva.length > 0
89:         ? aplicarDescontoVouchers(valorTotalBruto, vouchersAtivosParaReserva)
90:         : null,
91:     [vouchersAtivosParaReserva, valorTotalBruto]
92:   );
93: 
94:   const valorTotal = resultadoDesconto ? resultadoDesconto.valorFinal : valorTotalBruto;
95:   const valorSinal = useMemo(() => {
96:     if (valorTotal === 0) return 0;
97:     return calcularValorSinal(valorTotal);
98:   }, [valorTotal]);
99: 
100:   const valorPendente = useMemo(
101:     () => calcularValorPendente(valorTotal),
102:     [valorTotal]
103:   );
104: 
105:   // ── Handlers ────────────────────────────────────────────────────────────
106: 
107:   const handleToggleVoucher = useCallback((voucherId: string) => {
108:     setVouchersSelecionadosIds((prev) =>
109:       prev.includes(voucherId) ? prev.filter((id) => id !== voucherId) : [...prev, voucherId]
110:     );
111:   }, []);
112: 
113:   const handleLimparVouchers = useCallback(() => {
114:     setVouchersSelecionadosIds([]);
115:   }, []);
116: 
117:   const handleSelectData = useCallback((data: string) => {
118:     setDataSelecionada(data);
119:     setQuadraSelecionada(null);
120:     setHorariosSelecionados([]);
121:   }, []);
122: 
123:   /**
124:    * Chamado por QuadraHorarioItem: alterna um horário na quadra especificada.
125:    * Se o usuário clicar em uma quadra diferente da atual, altera a seleção para ela.
126:    * Múltiplos horários na mesma quadra devem ser estritamente consecutivos.
127:    */
128:   const handleToggleHorario = useCallback(
129:     (horario: string, quadraId: string) => {
130:       if (user?.bloqueado) {
131:         toast.error("Conta bloqueada para novas reservas", {
132:           description: "Sua conta está com restrição para novos agendamentos. Por favor, entre em contato para entender o motivo.",
133:         });
134:         return;
135:       }
136: 
137:       // Se clicar em quadra diferente, migra a seleção para a nova quadra
138:       if (quadraSelecionada !== null && quadraSelecionada !== quadraId) {
139:         setQuadraSelecionada(quadraId);
140:         setHorariosSelecionados([horario]);
141:         const nomeQuadra = QUADRAS.find((q) => q.id === quadraId)?.numero;
142:         toast.info(`Selecionada Quadra ${nomeQuadra}`);
143:         return;
144:       }
145: 
146:       setQuadraSelecionada(quadraId);
147: 
148:       setHorariosSelecionados((prev) => {
149:         if (prev.includes(horario)) {
150:           const next = prev.filter((h) => h !== horario);
151:           if (next.length === 0) setQuadraSelecionada(null);
152:           return next;
153:         }
154:         const next = [...prev, horario];
155:         if (!saoConsecutivos(next)) return prev;
156:         return next;
157:       });
158:     },
159:     [quadraSelecionada, user?.bloqueado]
160:   );
161: 
162:   const handleLimpar = useCallback(() => {
163:     setHorariosSelecionados([]);
164:     setQuadraSelecionada(null);
165:     setVouchersSelecionadosIds([]);
166:   }, []);
167: 
168:   const handleContinuar = useCallback(async () => {
169:     if (!quadraSelecionada || horariosSelecionados.length === 0) return;
170: 
171:     const tel = user?.telefone ? user.telefone.replace(/\D/g, "") : "";
172:     const estaBloqueado = Boolean(user?.bloqueado) || (tel ? await isTelefoneBloqueado(tel) : false);
173: 
174:     if (estaBloqueado) {
175:       toast.error("Conta bloqueada para novas reservas", {
176:         description: "Sua conta está com restrição para novos agendamentos. Por favor, entre em contato para entender o motivo.",
177:       });
178:       return;
179:     }
180: 
181:     for (const h of horariosSelecionados) {
182:       if (isHorarioExpirado(dataSelecionada, h, 10)) {
183:         toast.error("Horário expirado", {
184:           description: "O horário escolhido já passou ou está muito próximo (menos de 10 min). Por favor, escolha outro.",
185:         });
186:         return;
187:       }
188:     }
189: 
190:     const id = criarReservaEmProcessamento({
191:       quadraId: quadraSelecionada,
192:       data: dataSelecionada,
193:       horarios: horariosSelecionados,
194:       userId: user?.id,
195:     });
196:     setReservaIdAtual(id);
197:     setIsCarrinhoOpen(false);
198:     setEtapa("formulario");
199:   }, [
200:     quadraSelecionada,
201:     horariosSelecionados,
202:     dataSelecionada,
203:     user?.id,
204:     user?.bloqueado,
205:     user?.telefone,
206:     criarReservaEmProcessamento,
207:   ]);
208: 
209:   /** Formulário de dados e escolha de pagamento confirmados */
210:   const handleFormConfirmar = useCallback(
211:     (dados: DadosIdentificacao, tipoPagamento: "sinal" | "integral") => {
212:       if (!reservaIdAtual) return;
213:       setDadosForm(dados);
214:       setTipoPagamentoEscolhido(tipoPagamento);
215:       atualizarIdentificacao(reservaIdAtual, {
216:         nomeCliente: dados.nome,
217:         whatsappCliente: dados.whatsapp,
218:         cpfCliente: "",
219:         esporte: dados.esporte || undefined,
220:         observacoes: dados.observacoes || undefined,
221:       });
222: 
223:       const descontoVal = resultadoDesconto ? resultadoDesconto.valorDesconto : 0;
224:       const isGratis = valorTotal === 0 && vouchersAtivosParaReserva.length > 0;
225:       const codigosVouchers = vouchersAtivosParaReserva.map((v) => v.codigo);
226: 
227:       atualizarDadosCheckout(reservaIdAtual, {
228:         valorTotal,
229:         valorSinal: isGratis ? 0 : (tipoPagamento === "integral" ? valorTotal : valorSinal),
230:         valorPendente: isGratis ? 0 : (tipoPagamento === "integral" ? 0 : valorPendente),
231:         valorOriginal: valorTotalBruto,
232:         descontoFidelidade: descontoVal,
233:         vouchersUtilizados: codigosVouchers,
234:         reservaGratuitaFidelidade: isGratis,
235:         metodoPagamento: isGratis
236:           ? "fidelidade"
237:           : vouchersAtivosParaReserva.length > 0
238:           ? "misto"
239:           : "pix",
240:       });
241: 
242:       // Se a reserva for 100% coberta pelos vouchers de fidelidade (valorTotal === 0)
243:       if (isGratis) {
244:         confirmarPagamento(reservaIdAtual, "integral");
245: 
246:         // Consome os vouchers selecionados utilizados nesta reserva
247:         void consumirVouchersNoCheckout(
248:           vouchersAtivosParaReserva.map((v) => v.id),
249:           reservaIdAtual
250:         );
251:         setVouchersSelecionadosIds([]);
252: 
253:         // Se visitante sem conta, salva dados para convidar a criar senha
254:         if (!isAutenticado && dados) {
255:           setDadosUltimaReserva({
256:             id: reservaIdAtual,
257:             nome: dados.nome,
258:             whatsapp: dados.whatsapp,
259:           });
260:           setMostrarModalPosCadastro(true);
261:         }
262: 
263:         // Reseta estado local
264:         setEtapa(null);
265:         setReservaIdAtual(null);
266:         setDadosForm(null);
267:         setHorariosSelecionados([]);
268:         setQuadraSelecionada(null);
269: 
270:         const qtdVch = vouchersAtivosParaReserva.length;
271:         toast.success("Reserva Gratuita Confirmada! 🎉", {
272:           description: `Sua reserva foi 100% coberta com ${
273:             qtdVch > 1
274:               ? `seus ${qtdVch} vouchers de fidelidade`
275:               : "seu voucher de fidelidade"
276:           }! Bom jogo!`,
277:           duration: 7000,
278:         });
279:         return;
280:       }
281: 
282:       setEtapa("pix");
283:     },
284:     [
285:       reservaIdAtual,
286:       atualizarIdentificacao,
287:       atualizarDadosCheckout,
288:       valorTotal,
289:       valorTotalBruto,
290:       valorSinal,
291:       valorPendente,
292:       resultadoDesconto,
293:       vouchersAtivosParaReserva,
294:       confirmarPagamento,
295:       consumirVouchersNoCheckout,
296:       isAutenticado,
297:     ]
298:   );
299: 
300:   /**
301:    * Simula pagamento Pix — confirmação com o tipo escolhido previamente.
302:    */
303:   const handleSimularPagamento = useCallback(
304:     (tipo: "sinal" | "integral") => {
305:       if (!reservaIdAtual) return;
306: 
307:       // Validação de 1 minuto antes do início do primeiro horário
308:       if (horariosSelecionados.length > 0) {
309:         const primeiroHorario = [...horariosSelecionados].sort()[0];
310:         if (isHorarioExpirado(dataSelecionada, primeiroHorario, 1)) {
311:            toast.error("Tempo esgotado para pagamento", {
312:              description: "O pagamento deve ser feito até 1 minuto antes do início do horário.",
313:            });
314:            return;
315:         }
316:       }
317: 
318:       confirmarPagamento(reservaIdAtual, tipo);
319: 
320:       // Consome os vouchers de fidelidade selecionados se foram aplicados nesta reserva
321:       if (vouchersAtivosParaReserva.length > 0 && reservaIdAtual) {
322:         void consumirVouchersNoCheckout(
323:           vouchersAtivosParaReserva.map((v) => v.id),
324:           reservaIdAtual
325:         );
326:         setVouchersSelecionadosIds([]);
327:       }
328: 
329:       // Se visitante sem conta, salva dados para convidar a criar senha
330:       if (!isAutenticado && dadosForm) {
331:         setDadosUltimaReserva({
332:           id: reservaIdAtual,
333:           nome: dadosForm.nome,
334:           whatsapp: dadosForm.whatsapp,
335:         });
336:         setMostrarModalPosCadastro(true);
337:       }
338: 
339:       // Reseta estado local
340:       setEtapa(null);
341:       setReservaIdAtual(null);
342:       setDadosForm(null);
343:       setHorariosSelecionados([]);
344:       setQuadraSelecionada(null);
345: 
346:       const descricao =
347:         tipo === "integral"
348:           ? "Pagamento integral confirmado! ✅"
349:           : "Sinal confirmado. O restante será pago no local. 👍";
350: 
351:       toast.success("Mensagem enviada no WhatsApp 📱", {
352:         description: descricao,
353:         duration: 6000,
354:       });
355:     },
356:     [
357:       reservaIdAtual,
358:       confirmarPagamento,
359:       isAutenticado,
360:       dadosForm,
361:       dataSelecionada,
362:       horariosSelecionados,
363:       vouchersAtivosParaReserva,
364:       consumirVouchersNoCheckout,
365:     ]
366:   );
367: 
368:   /** Cancela checkout e libera o lock */
369:   const handleCancelarCheckout = useCallback(() => {
370:     if (reservaIdAtual) liberarLock(reservaIdAtual);
371:     setEtapa(null);
372:     setReservaIdAtual(null);
373:     setDadosForm(null);
374:   }, [reservaIdAtual, liberarLock]);
375: 
376:   // ── Render ──────────────────────────────────────────────────────────────
377: 
378:   const carrinhoContent = (
379:     <CarrinhoLateral
380:       quadraId={quadraSelecionada}
381:       data={dataSelecionada}
382:       horariosSelecionados={horariosSelecionados}
383:       valorTotal={valorTotalBruto}
384:       valorSinal={calcularValorSinal(valorTotalBruto)}
385:       valorPendente={calcularValorPendente(valorTotalBruto)}
386:       onContinuar={handleContinuar}
387:       onLimpar={handleLimpar}
388:       vouchersSelecionadosIds={vouchersSelecionadosIds}
389:       onToggleVoucher={handleToggleVoucher}
390:       onLimparVouchers={handleLimparVouchers}
391:       vouchersDisponiveis={progresso.vouchersDisponiveis}
392:     />
393:   );
394: 
395:   return (
396:     <>
397:       <div className="min-h-screen bg-slate-950">
398:         {/* ── Header ──────────────────────────────────────────────────── */}
399:         <header className="sticky top-0 z-30 border-b border-slate-800 bg-slate-950/80 backdrop-blur-md">
400:           <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
401:             <div className="flex items-center gap-2">
402:               <span className="text-2xl">🏟️</span>
403:               <div>
404:                 <span className="font-black text-white text-lg tracking-tight">
405:                   Reservei
406:                 </span>
407:                 <span className="hidden sm:inline text-slate-500 text-sm ml-2">
408:                   · Complexo Esportivo
409:                 </span>
410:               </div>
411:             </div>
412:             <div className="flex items-center gap-3">
413:               {user ? (
414:                 <Link href="/minha-conta">
415:                   <Button
416:                     size="sm"
417:                     variant="outline"
418:                     className="bg-slate-900 border-slate-700 hover:border-emerald-500/50 text-slate-200 hover:text-white rounded-full px-3.5 py-1 text-xs flex items-center gap-2"
419:                   >
420:                     <div className="w-5 h-5 rounded-full bg-emerald-500/20 text-emerald-400 flex items-center justify-center font-bold text-[10px]">
421:                       {user.nome.charAt(0).toUpperCase()}
422:                     </div>
423:                     <span className="font-semibold max-w-[100px] truncate sm:max-w-none">
424:                       {user.nome.split(" ")[0]}
425:                     </span>
426:                     <span className="text-[10px] text-emerald-400 bg-emerald-500/10 px-1.5 py-0.5 rounded-full hidden sm:inline">
427:                       Minhas Reservas
428:                     </span>
429:                   </Button>
430:                 </Link>
431:               ) : (
432:                 <div className="flex items-center gap-2">
433:                   <Link href="/login">
434:                     <Button
435:                       size="sm"
436:                       variant="ghost"
437:                       className="text-slate-300 hover:text-white text-xs font-semibold px-3 py-1"
438:                     >
439:                       Entrar
440:                     </Button>
441:                   </Link>
442:                   <Link href="/cadastro">
443:                     <Button
444:                       size="sm"
445:                       className="bg-emerald-500 hover:bg-emerald-600 text-slate-950 font-bold rounded-full text-xs px-3.5 py-1 shadow-md shadow-emerald-500/10"
446:                     >
447:                       Criar Conta
448:                     </Button>
449:                   </Link>
450:                 </div>
451:               )}
452:             </div>
453:           </div>
454:         </header>
455: 
456:         {/* ── Layout Principal ─────────────────────────────────────────── */}
457:         <div className="max-w-7xl mx-auto px-4 py-6 md:grid md:grid-cols-[1fr_320px] lg:grid-cols-[1fr_360px] md:gap-6 lg:gap-8 md:items-start">
458:           {/* Coluna esquerda: seleção */}
459:           <main className="space-y-6 pb-28 md:pb-6">
460:             {/* Alerta de conta bloqueada */}
461:             {user?.bloqueado && (
462:               <div className="bg-red-950/40 border border-red-500/30 rounded-2xl p-4 sm:p-5 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 text-red-200 shadow-lg">
463:                 <div className="flex items-start gap-3.5">
464:                   <div className="w-10 h-10 rounded-xl bg-red-500/10 border border-red-500/25 text-red-400 flex items-center justify-center flex-shrink-0 mt-0.5 text-lg">
465:                     ⚠️
466:                   </div>
467:                   <div>
468:                     <h3 className="font-bold text-sm text-red-100">
469:                       Conta Temporariamente Restrita para Reservas
470:                     </h3>
471:                     <p className="text-xs text-red-300/90 mt-1 leading-relaxed">
472:                       Identificamos uma restrição em sua conta para agendamentos online. Para entender o motivo ou solicitar o desbloqueio, entre em contato com a administração.
473:                     </p>
474:                   </div>
475:                 </div>
476:                 <a
477:                   href={`https://wa.me/5500000000000?text=${encodeURIComponent("Olá, gostaria de entender o motivo do bloqueio da minha conta no Reservei.")}`}
478:                   target="_blank"
479:                   rel="noopener noreferrer"
480:                   className="w-full sm:w-auto px-4 py-2.5 rounded-xl bg-red-500/20 hover:bg-red-500/30 text-red-200 border border-red-500/40 font-bold text-xs flex items-center justify-center gap-2 whitespace-nowrap transition-colors"
481:                 >
482:                   Falar com Suporte
483:                 </a>
484:               </div>
485:             )}
486: 
487:             {/* Calendário horizontal */}
488:             <section>
489:               <CalendarioSelector
490:                 dias={dias}
491:                 dataSelecionada={dataSelecionada}
492:                 onSelectData={handleSelectData}
493:               />
494:             </section>
495: 
496:             {/* Título da seção */}
497:             <div>
498:               <p className="text-xs font-semibold uppercase tracking-widest text-slate-500">
499:                 Quadras disponíveis
500:               </p>
501:               <p className="text-[11px] text-slate-600 mt-1">
502:                 Selecione os horários desejados diretamente na quadra.
503:               </p>
504:             </div>
505: 
506:             {/* Quadras sempre expandidas verticalmente */}
507:             {QUADRAS.map((quadra) => {
508:               const isAtiva = quadraSelecionada === quadra.id;
509:               const horariosOcupados = getHorariosOcupados(
510:                 dataSelecionada,
511:                 quadra.id
512:               );
513: 
514:               return (
515:                 <QuadraHorarioItem
516:                   key={`${quadra.id}-${dataSelecionada}`}
517:                   quadra={quadra}
518:                   dataSelecionada={dataSelecionada}
519:                   horariosSelecionados={isAtiva ? horariosSelecionados : []}
520:                   horariosOcupados={horariosOcupados}
521:                   avisosEscolinha={getAvisosEscolinha(dataSelecionada, quadra.id)}
522:                   isAtiva={isAtiva}
523:                   onToggleHorario={handleToggleHorario}
524:                 />
525:               );
526:             })}
527: 
528:             {/* Mural de Vagas Abertas (Versão Mobile) */}
