import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { CalendarCheck } from "lucide-react";
import { cn } from "@/lib/utils";
import { useHeaderRolado } from "@/hooks/useHeaderRolado";
import { useSecaoAtiva } from "@/hooks/useSecaoAtiva";
import { getSecoesDoMenu, rolarParaSecao } from "@/lib/landingPage/navegacao";
import { SECAO_IDS, SECOES_LANDING_PAGE } from "@/lib/landingPage/secoes";
import type { SecaoLandingId, SecaoLandingPage } from "@/lib/landingPage/types";
import { AcoesUsuarioHeader } from "./AcoesUsuarioHeader";
import { ListaLinksNavegacao } from "./ListaLinksNavegacao";
import { LogoReservei } from "./LogoReservei";
import { MenuNavegacaoMobile } from "./MenuNavegacaoMobile";

/**
 * Tempo (ms) aguardado após fechar o menu mobile antes de rolar a página.
 * Corresponde à animação de saída do Sheet, garantindo que o bloqueio de
 * rolagem do painel já tenha sido removido.
 */
export const ATRASO_ROLAGEM_APOS_MENU_MS = 220;

/** Props do {@link LandingHeader}. */
export interface LandingHeaderProps {
  /** Catálogo de seções (injeção para testes). Padrão: {@link SECOES_LANDING_PAGE}. */
  secoes?: readonly SecaoLandingPage[];
}

/**
 * Cabeçalho fixo da Landing Page.
 *
 * Comportamentos (SPEC/2026-10-06-lp-base-navegacao.md §2.1):
 * - Sticky no topo; fundo transparente que fica sólido ao rolar.
 * - Links de âncora com rolagem suave e destaque da seção ativa (scroll spy).
 * - Ações de conta (Entrar/Criar Conta ou Minhas Reservas).
 * - CTA "Agendar Agora" que leva ao fluxo de reserva.
 * - Menu hambúrguer em telas menores que `lg`.
 *
 * @example
 * <LandingHeader />
 */
export function LandingHeader({ secoes = SECOES_LANDING_PAGE }: LandingHeaderProps) {
  const rolado = useHeaderRolado();
  const secoesMenu = useMemo(() => getSecoesDoMenu(secoes), [secoes]);
  const idsObservados = useMemo(() => secoes.map((s) => s.id), [secoes]);
  const secaoAtiva = useSecaoAtiva(idsObservados);

  const [menuAberto, setMenuAberto] = useState(false);
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    return () => {
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
    };
  }, []);

  const navegar = useCallback(
    (id: SecaoLandingId) => {
      if (!menuAberto) {
        rolarParaSecao(id);
        return;
      }
      setMenuAberto(false);
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
      timeoutRef.current = setTimeout(() => {
        rolarParaSecao(id);
        timeoutRef.current = null;
      }, ATRASO_ROLAGEM_APOS_MENU_MS);
    },
    [menuAberto]
  );

  const agendarAgora = useCallback(() => navegar(SECAO_IDS.INICIO), [navegar]);

  return (
    <header
      data-rolado={rolado ? "true" : "false"}
      className={cn(
        "sticky top-0 z-30 border-b transition-colors duration-300",
        rolado
          ? "bg-slate-950/85 backdrop-blur-md border-slate-800 shadow-lg shadow-black/20"
          : "bg-transparent border-transparent"
      )}
    >
      <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between gap-4">
        <a
          href={`#${SECAO_IDS.INICIO}`}
          id="header-logo"
          aria-label="Ir para o início"
          onClick={(evento) => {
            evento.preventDefault();
            navegar(SECAO_IDS.INICIO);
          }}
          className="rounded-lg focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-emerald-500/60"
        >
          <LogoReservei />
        </a>

        <ListaLinksNavegacao
          secoes={secoesMenu}
          secaoAtiva={secaoAtiva}
          onNavegar={navegar}
          idPrefixo="nav-desktop"
          ariaLabel="Navegação principal"
          className="hidden lg:block"
        />

        <div className="flex items-center gap-2 sm:gap-3">
          <button
            type="button"
            id="header-agendar-agora"
            onClick={agendarAgora}
            className="hidden md:inline-flex items-center gap-2 rounded-full border border-emerald-500/40 bg-emerald-500/10 hover:bg-emerald-500/20 text-emerald-300 hover:text-emerald-200 text-xs font-bold px-3.5 py-1.5 transition-colors"
          >
            <CalendarCheck className="w-3.5 h-3.5" aria-hidden="true" />
            Agendar Agora
          </button>

          <AcoesUsuarioHeader />

          <MenuNavegacaoMobile
            aberto={menuAberto}
            onAbertoChange={setMenuAberto}
            secoes={secoesMenu}
            secaoAtiva={secaoAtiva}
            onNavegar={navegar}
            onAgendarAgora={agendarAgora}
          />
        </div>
      </div>
    </header>
  );
}

import type { ReactNode } from "react";
import { cn } from "@/lib/utils";
import type { SecaoLandingPage } from "@/lib/landingPage/types";

/** Props da {@link SecaoLanding}. */
export interface SecaoLandingProps {
  /** Metadados da seção (id, título, subtítulo e rótulo). */
  secao: SecaoLandingPage;
  /** Conteúdo da seção. */
  children: ReactNode;
  /** Aplica fundo levemente destacado (útil para alternar seções). */
  destaque?: boolean;
  /** Classes extras do `<section>`. */
  className?: string;
}

/**
 * Contêiner padrão de uma seção da Landing Page.
 *
 * Garante para TODAS as seções:
 * - `id` igual ao da âncora (navegação por `#id`);
 * - `scroll-margin-top` para não ficar escondida atrás do cabeçalho fixo;
 * - cabeçalho semântico (`h2`) ligado via `aria-labelledby`;
 * - espaçamento e largura máxima consistentes.
 *
 * As specs seguintes devem reutilizar este componente ao implementar o
 * conteúdo real de cada seção.
 *
 * @example
 * <SecaoLanding secao={getSecaoPorId("estrutura")!}>
 *   <GaleriaEstrutura />
 * </SecaoLanding>
 */
export function SecaoLanding({ secao, children, destaque = false, className }: SecaoLandingProps) {
  const tituloId = `${secao.id}-titulo`;

  return (
    <section
      id={secao.id}
      aria-labelledby={tituloId}
      className={cn(
        "scroll-mt-20 py-16 md:py-20 border-t border-slate-800/60",
        destaque && "bg-slate-900/30",
        className
      )}
    >
      <div className="max-w-7xl mx-auto px-4">
        <header className="mb-8 md:mb-10 max-w-2xl">
          <p className="text-xs font-semibold uppercase tracking-widest text-emerald-400">
            {secao.rotuloMenu}
          </p>
          <h2 id={tituloId} className="mt-2 text-2xl md:text-3xl font-black text-white tracking-tight">
            {secao.titulo}
          </h2>
          <p className="mt-2 text-sm md:text-base text-slate-400">{secao.subtitulo}</p>
        </header>
        {children}
      </div>
    </section>
  );
}

