import { act, renderHook } from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { useSecaoAtiva } from "@/hooks/useSecaoAtiva";
import type { SecaoLandingId } from "@/lib/landingPage/types";

type CallbackIO = (entries: Partial<IntersectionObserverEntry>[]) => void;

/** Dublê de IntersectionObserver que permite disparar interseções manualmente. */
class IntersectionObserverFake {
  static instancias: IntersectionObserverFake[] = [];
  readonly observados: Element[] = [];
  readonly disconnect = vi.fn();
  constructor(
    public readonly callback: CallbackIO,
    public readonly opcoes?: IntersectionObserverInit
  ) {
    IntersectionObserverFake.instancias.push(this);
  }
  observe(elemento: Element) {
    this.observados.push(elemento);
  }
  unobserve() {}
  takeRecords() {
    return [];
  }
  disparar(entries: { id: string; ratio: number; visivel?: boolean }[]) {
    this.callback(
      entries.map(({ id, ratio, visivel = ratio > 0 }) => ({
        target: document.getElementById(id) as Element,
        intersectionRatio: ratio,
        isIntersecting: visivel,
      }))
    );
  }
}

const IDS: SecaoLandingId[] = ["inicio", "estrutura", "contato"];
const ioOriginal = (window as unknown as { IntersectionObserver?: unknown }).IntersectionObserver;

function instalarIO(valor: unknown) {
  Object.defineProperty(window, "IntersectionObserver", {
    value: valor,
    writable: true,
    configurable: true,
  });
}

describe("useSecaoAtiva", () => {
  beforeEach(() => {
    IntersectionObserverFake.instancias = [];
    document.body.innerHTML = IDS.map((id) => `<section id="${id}"></section>`).join("");
    instalarIO(IntersectionObserverFake);
  });

  afterEach(() => {
    instalarIO(ioOriginal);
    document.body.innerHTML = "";
    vi.restoreAllMocks();
  });

  it("retorna a primeira seção como estado inicial", () => {
    const { result } = renderHook(() => useSecaoAtiva(IDS));
    expect(result.current).toBe("inicio");
  });

  it("observa todas as seções existentes no DOM", () => {
    renderHook(() => useSecaoAtiva(IDS));
    const io = IntersectionObserverFake.instancias[0];
    expect(io.observados.map((el) => el.id)).toEqual(IDS);
  });

  it("ignora seções que não existem no DOM", () => {
    document.getElementById("contato")?.remove();
    renderHook(() => useSecaoAtiva(IDS));
    const io = IntersectionObserverFake.instancias[0];
    expect(io.observados.map((el) => el.id)).toEqual(["inicio", "estrutura"]);
  });

  it("atualiza para a seção mais visível", () => {
    const { result } = renderHook(() => useSecaoAtiva(IDS));
    const io = IntersectionObserverFake.instancias[0];

    act(() => io.disparar([{ id: "inicio", ratio: 0.2 }, { id: "estrutura", ratio: 0.8 }]));
    expect(result.current).toBe("estrutura");

    act(() => io.disparar([{ id: "estrutura", ratio: 0 }, { id: "contato", ratio: 0.5 }]));
    expect(result.current).toBe("contato");
  });

  it("mantém a seção atual quando nada está visível", () => {
    const { result } = renderHook(() => useSecaoAtiva(IDS));
    const io = IntersectionObserverFake.instancias[0];

    act(() => io.disparar([{ id: "estrutura", ratio: 0.6 }]));
    act(() => io.disparar([{ id: "estrutura", ratio: 0 }]));
    expect(result.current).toBe("estrutura");
  });

  it("repassa rootMargin e thresholds customizados", () => {
    renderHook(() => useSecaoAtiva(IDS, { rootMargin: "0px", thresholds: [0.5] }));
    const io = IntersectionObserverFake.instancias[0];
    expect(io.opcoes).toEqual({ rootMargin: "0px", threshold: [0.5] });
  });

  it("desconecta o observer ao desmontar", () => {
    const { unmount } = renderHook(() => useSecaoAtiva(IDS));
    const io = IntersectionObserverFake.instancias[0];
    unmount();
    expect(io.disconnect).toHaveBeenCalled();
  });

  it("funciona sem IntersectionObserver (fallback estável)", () => {
    instalarIO(undefined);
    const { result } = renderHook(() => useSecaoAtiva(IDS));
    expect(result.current).toBe("inicio");
  });

  it("não quebra se o IntersectionObserver lançar erro na criação", () => {
    vi.spyOn(console, "error").mockImplementation(() => undefined);
    instalarIO(
      class {
        constructor() {
          throw new Error("não suportado");
        }
      }
    );
    const { result } = renderHook(() => useSecaoAtiva(IDS));
    expect(result.current).toBe("inicio");
    expect(console.error).toHaveBeenCalled();
  });

  it("retorna null para lista vazia", () => {
    const { result } = renderHook(() => useSecaoAtiva([]));
    expect(result.current).toBeNull();
  });
});

import React from "react";
import { fireEvent, render, screen, waitFor, within } from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { LandingHeader } from "@/components/landing/LandingHeader";

// ── Mocks ──────────────────────────────────────────────────────────────────

vi.mock("next/link", () => ({
  default: ({ href, children, ...rest }: { href: string; children: React.ReactNode }) => (
    <a href={href} {...rest}>
      {children}
    </a>
  ),
}));

let mockUserAuth: { user: { id: string; nome: string; telefone: string } | null } = { user: null };

vi.mock("@/hooks/useUserAuth", () => ({
  useUserAuth: () => mockUserAuth,
}));

// ── Helpers ────────────────────────────────────────────────────────────────

const SECOES_DOM = ["inicio", "estrutura", "escolinhas", "eventos", "contato"];

function renderizarPagina() {
  return render(
    <>
      <LandingHeader />
      {SECOES_DOM.map((id) => (
        <section key={id} id={id} />
      ))}
    </>
  );
}

function definirScrollY(valor: number) {
  Object.defineProperty(window, "scrollY", { value: valor, writable: true, configurable: true });
}

describe("LandingHeader - Componente", () => {
  let scrollSpy: ReturnType<typeof vi.fn>;
  const scrollOriginal = Element.prototype.scrollIntoView;

  beforeEach(() => {
    mockUserAuth = { user: null };
    scrollSpy = vi.fn();
    Element.prototype.scrollIntoView = scrollSpy as unknown as typeof Element.prototype.scrollIntoView;
    definirScrollY(0);
    window.history.replaceState(null, "", "/");
  });

  afterEach(() => {
    Element.prototype.scrollIntoView = scrollOriginal;
    vi.clearAllMocks();
  });

  it("renderiza os links de navegação definidos na spec com âncoras corretas", () => {
    renderizarPagina();
    const nav = screen.getByRole("navigation", { name: "Navegação principal" });
    const links = within(nav).getAllByRole("link");

    expect(links.map((l) => l.textContent)).toEqual([
      "Início",
      "Estrutura",
      "Escolinhas",
      "Eventos",
      "Contato",
    ]);
    expect(links.map((l) => l.getAttribute("href"))).toEqual([
      "#inicio",
      "#estrutura",
      "#escolinhas",
      "#eventos",
      "#contato",
    ]);
  });

  it("destaca a primeira seção (reserva) como ativa por padrão", () => {
    renderizarPagina();
    expect(document.getElementById("nav-desktop-inicio")).toHaveAttribute("aria-current", "location");
    expect(document.getElementById("nav-desktop-estrutura")).not.toHaveAttribute("aria-current");
  });

  it("exibe Entrar e Criar Conta para visitantes", () => {
    renderizarPagina();
    expect(screen.getByText("Entrar")).toBeInTheDocument();
    expect(screen.getByText("Criar Conta")).toBeInTheDocument();
    expect(document.getElementById("header-entrar")).toHaveAttribute("href", "/login");
    expect(document.getElementById("header-criar-conta")).toHaveAttribute("href", "/cadastro");
  });

  it("exibe o primeiro nome e o atalho de Minhas Reservas para cliente logado", () => {
    mockUserAuth = { user: { id: "u1", nome: "Leonardo Ribeiro", telefone: "11999998888" } };
    renderizarPagina();

    expect(screen.getByText("Leonardo")).toBeInTheDocument();
    expect(screen.getByText("Minhas Reservas")).toBeInTheDocument();
    expect(document.getElementById("header-minha-conta")).toHaveAttribute("href", "/minha-conta");
    expect(screen.queryByText("Entrar")).not.toBeInTheDocument();
  });

  it("rola suavemente até a seção ao clicar em um link do menu", () => {
    renderizarPagina();
    fireEvent.click(document.getElementById("nav-desktop-estrutura") as HTMLElement);

    expect(scrollSpy).toHaveBeenCalledTimes(1);
    expect(scrollSpy.mock.contexts[0]).toBe(document.getElementById("estrutura"));
    expect(window.location.hash).toBe("#estrutura");
  });

  it("não intercepta Ctrl+Clique (permite abrir em nova aba)", () => {
    renderizarPagina();
    fireEvent.click(document.getElementById("nav-desktop-contato") as HTMLElement, { ctrlKey: true });
    expect(scrollSpy).not.toHaveBeenCalled();
  });

  it("CTA 'Agendar Agora' leva ao fluxo de reserva", () => {
    renderizarPagina();
    fireEvent.click(document.getElementById("header-agendar-agora") as HTMLElement);
    expect(scrollSpy.mock.contexts[0]).toBe(document.getElementById("inicio"));
  });

  it("clicar no logo leva ao início", () => {
    renderizarPagina();
    fireEvent.click(screen.getByLabelText("Ir para o início"));
    expect(scrollSpy.mock.contexts[0]).toBe(document.getElementById("inicio"));
  });

  it("fica transparente no topo e sólido após rolar", () => {
    const { container } = renderizarPagina();
    const header = container.querySelector("header") as HTMLElement;
    expect(header).toHaveAttribute("data-rolado", "false");

    definirScrollY(300);
    fireEvent.scroll(window);
    expect(header).toHaveAttribute("data-rolado", "true");
  });

  it("menu mobile abre, navega e fecha antes de rolar", async () => {
    renderizarPagina();
    const botaoMenu = screen.getByLabelText("Abrir menu de navegação");
    expect(botaoMenu).toHaveAttribute("aria-expanded", "false");

    fireEvent.click(botaoMenu);
    expect(botaoMenu).toHaveAttribute("aria-expanded", "true");

    const linkMobile = await waitFor(() => {
      const el = document.getElementById("nav-mobile-eventos");
      expect(el).not.toBeNull();
      return el as HTMLElement;
    });

    fireEvent.click(linkMobile);
    expect(botaoMenu).toHaveAttribute("aria-expanded", "false");

    await waitFor(() => {
      expect(scrollSpy).toHaveBeenCalled();
    });
    expect(scrollSpy.mock.contexts[0]).toBe(document.getElementById("eventos"));
  });
});

