"use client";

import { useEffect, useState } from "react";

/**
 * Hook customizado para calcular o percentual de rolagem vertical da página (0 a 100%).
 *
 * Utilizado para alimentar a barra visual de progresso da Landing Page, oferecendo
 * feedback imediato e refinado sobre a posição atual do usuário ao longo da navegação.
 *
 * - Usa listeners de eventos com flag `passive: true` para não impactar a taxa de quadros (60/120 FPS).
 * - Trata redimensionamentos de tela para recalcular os limites da página dinamicamente.
 * - Garante retorno seguro entre `0` e `100`.
 *
 * @returns Percentual numérico arredondado ou decimal entre 0 e 100.
 *
 * @example
 * ```tsx
 * const progresso = useProgressoRolagem();
 * <div style={{ width: `${progresso}%` }} className="h-0.5 bg-emerald-500" />
 * ```
 */
export function useProgressoRolagem(): number {
  const [progresso, setProgresso] = useState<number>(0);

  useEffect(() => {
    if (typeof window === "undefined" || typeof document === "undefined") {
      return;
    }

    const recalcular = () => {
      const scrollAtual = window.scrollY || document.documentElement.scrollTop || 0;
      const alturaTotal = document.documentElement.scrollHeight - window.innerHeight;

      if (alturaTotal <= 0) {
        setProgresso(0);
        return;
      }

      const percentual = Math.min(100, Math.max(0, (scrollAtual / alturaTotal) * 100));
      setProgresso(percentual);
    };

    recalcular();
    window.addEventListener("scroll", recalcular, { passive: true });
    window.addEventListener("resize", recalcular, { passive: true });

    return () => {
      window.removeEventListener("scroll", recalcular);
      window.removeEventListener("resize", recalcular);
    };
  }, []);

  return progresso;
}

"use client";

import { useEffect } from "react";
import Lenis from "lenis";

/** Interface estendida do objeto Window para registrar a instância ativa do Lenis. */
declare global {
  interface Window {
    __lenis?: Lenis;
  }
}

/** Props do componente {@link SmoothScrollProvider}. */
export interface SmoothScrollProviderProps {
  /** Elementos filhos da aplicação envolvidos pelo provedor de rolagem suave. */
  children: React.ReactNode;
}

/**
 * Provedor de rolagem suave inercial contínua (Lenis) para a Landing Page.
 *
 * Transforma a experiência de rolagem da página inteira, aplicando desaceleração
 * inercial física e amortecimento a cada movimento da rodinha do mouse ou do trackpad:
 * - Elimina os saltos mecânicos e truncados nativos do navegador (ex.: saltos fixos de 100px).
 * - Sincroniza um loop contínuo de interpolação via `requestAnimationFrame`.
 * - Fornece suporte a touchpads e dispositivos com alta taxa de atualização (120Hz/ProMotion).
 * - Registra a instância ativa em `window.__lenis` para que ações de navegação por âncora
 *   possam reutilizar o mesmo motor de interpolação.
 * - Detecta preferências de acessibilidade (`prefers-reduced-motion`) nativamente.
 *
 * @param props - Propriedades contendo os filhos React a serem renderizados.
 *
 * @example
 * ```tsx
 * <SmoothScrollProvider>
 *   <LandingHeader />
 *   <main>{conteudo}</main>
 * </SmoothScrollProvider>
 * ```
 */
export function SmoothScrollProvider({ children }: SmoothScrollProviderProps) {
  useEffect(() => {
    // Não inicializar no servidor ou em ambientes de testes sem navegador completo (ex: JSDOM)
    if (
      typeof window === "undefined" ||
      typeof Window === "undefined" ||
      typeof window.matchMedia !== "function" ||
      process.env.NODE_ENV === "test"
    ) {
      return;
    }

    const lenis = new Lenis({
      duration: 1.15,
      easing: (t: number) => Math.min(1, 1.001 - Math.pow(2, -10 * t)),
      orientation: "vertical",
      gestureOrientation: "vertical",
      smoothWheel: true,
      wheelMultiplier: 1.05,
      touchMultiplier: 1.5,
    });

    window.__lenis = lenis;

    let rafId: number;
    const onRaf = (time: number) => {
      lenis.raf(time);
      rafId = requestAnimationFrame(onRaf);
    };
    rafId = requestAnimationFrame(onRaf);

    return () => {
      cancelAnimationFrame(rafId);
      lenis.destroy();
      delete window.__lenis;
    };
  }, []);

  return <>{children}</>;
}

