"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { CalendarCheck } from "lucide-react";
import { cn } from "@/lib/utils";
import { useHeaderRolado } from "@/hooks/useHeaderRolado";
import { useSecaoAtiva } from "@/hooks/useSecaoAtiva";
import { getSecoesDoMenu, rolarParaSecao } from "@/lib/landingPage/navegacao";
import { SECAO_IDS, SECOES_LANDING_PAGE } from "@/lib/landingPage/secoes";
import type { SecaoLandingId, SecaoLandingPage } from "@/lib/landingPage/types";
import { AcoesUsuarioHeader } from "./AcoesUsuarioHeader";
import { ListaLinksNavegacao } from "./ListaLinksNavegacao";
import { LogoReservei } from "./LogoReservei";
import { MenuNavegacaoMobile } from "./MenuNavegacaoMobile";

/**
 * Tempo (ms) aguardado após fechar o menu mobile antes de rolar a página.
 * Corresponde à animação de saída do Sheet, garantindo que o bloqueio de
 * rolagem do painel já tenha sido removido.
 */
export const ATRASO_ROLAGEM_APOS_MENU_MS = 220;

/** Props do {@link LandingHeader}. */
export interface LandingHeaderProps {
  /** Catálogo de seções (injeção para testes). Padrão: {@link SECOES_LANDING_PAGE}. */
  secoes?: readonly SecaoLandingPage[];
}

/**
 * Cabeçalho fixo da Landing Page.
 *
 * Comportamentos (SPEC/2026-10-06-lp-base-navegacao.md §2.1):
 * - Sticky no topo (fixo durante toda a rolagem); fundo transparente que fica sólido ao rolar.
 * - Links de âncora com rolagem suave e destaque da seção ativa (scroll spy).
 * - Ações de conta (Entrar/Criar Conta ou Minhas Reservas).
 * - CTA "Agendar Agora" que leva ao fluxo de reserva.
 * - Menu hambúrguer em telas menores que `lg`.
 *
 * @example
 * <LandingHeader />
 */
export function LandingHeader({ secoes = SECOES_LANDING_PAGE }: LandingHeaderProps) {
  const rolado = useHeaderRolado();
  const secoesMenu = useMemo(() => getSecoesDoMenu(secoes), [secoes]);
  const idsObservados = useMemo(() => secoes.map((s) => s.id), [secoes]);
  const secaoAtiva = useSecaoAtiva(idsObservados);

  const [menuAberto, setMenuAberto] = useState(false);
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    return () => {
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
    };
  }, []);

  const navegar = useCallback(
    (id: SecaoLandingId) => {
      if (!menuAberto) {
        rolarParaSecao(id);
        return;
      }
      setMenuAberto(false);
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
      timeoutRef.current = setTimeout(() => {
        rolarParaSecao(id);
        timeoutRef.current = null;
      }, ATRASO_ROLAGEM_APOS_MENU_MS);
    },
    [menuAberto]
  );

  const agendarAgora = useCallback(() => navegar(SECAO_IDS.INICIO), [navegar]);

  return (
    <header
      data-rolado={rolado ? "true" : "false"}
      className={cn(
        "sticky top-0 z-30 border-b transition-colors duration-300",
        rolado
          ? "bg-slate-950/85 backdrop-blur-md border-slate-800 shadow-lg shadow-black/20"
          : "bg-transparent border-transparent"
      )}
    >
      <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between gap-4">
        <a
          href={`#${SECAO_IDS.INICIO}`}
          id="header-logo"
          aria-label="Ir para o início"
          onClick={(evento) => {
            evento.preventDefault();
            navegar(SECAO_IDS.INICIO);
          }}
          className="rounded-lg focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-emerald-500/60"
        >
          <LogoReservei />
        </a>

        <ListaLinksNavegacao
          secoes={secoesMenu}
          secaoAtiva={secaoAtiva}
          onNavegar={navegar}
          idPrefixo="nav-desktop"
          ariaLabel="Navegação principal"
          className="hidden lg:block"
        />

        <div className="flex items-center gap-2 sm:gap-3">
          <button
            type="button"
            id="header-agendar-agora"
            onClick={agendarAgora}
            className="hidden md:inline-flex items-center gap-2 rounded-full border border-emerald-500/40 bg-emerald-500/10 hover:bg-emerald-500/20 text-emerald-300 hover:text-emerald-200 text-xs font-bold px-3.5 py-1.5 transition-colors"
          >
            <CalendarCheck className="w-3.5 h-3.5" aria-hidden="true" />
            Agendar Agora
          </button>

          <AcoesUsuarioHeader />

          <MenuNavegacaoMobile
            aberto={menuAberto}
            onAbertoChange={setMenuAberto}
            secoes={secoesMenu}
            secaoAtiva={secaoAtiva}
            onNavegar={navegar}
            onAgendarAgora={agendarAgora}
          />
        </div>
      </div>
    </header>
  );
}

"use client";

import { useEffect } from "react";
import Lenis from "lenis";

/** Interface estendida do objeto Window para registrar a instância ativa do Lenis. */
declare global {
  interface Window {
    __lenis?: Lenis;
  }
}

/** Props do componente {@link SmoothScrollProvider}. */
export interface SmoothScrollProviderProps {
  /** Elementos filhos da aplicação envolvidos pelo provedor de rolagem suave. */
  children: React.ReactNode;
}

/**
 * ─────────────────────────────────────────────────────────────────────────────
 * CONFIGURAÇÃO DA VELOCIDADE E SENSIBILIDADE DO SCROLL (LENIS)
 * ─────────────────────────────────────────────────────────────────────────────
 * Ajuste estas constantes para calibrar a sensação física da rolagem na página:
 *
 * 1. DURACAO_ROLAGEM_SEGUNDOS:
 *    Tempo de desaceleração (em segundos). Menor = mais rápido/ágil (ex.: 0.7s a 0.85s).
 *
 * 2. MULTIPLICADOR_RODA_MOUSE:
 *    Quantidade de pixels avançados a cada "clique" ou giro da rodinha do mouse.
 *    Aumente (ex.: 1.2, 1.4, 1.6) para andar mais distância por giro do mouse.
 *
 * 3. MULTIPLICADOR_TOUCHPAD:
 *    Sensibilidade de movimento para touchpads de notebook e telas touch.
 * ─────────────────────────────────────────────────────────────────────────────
 */
export const CONFIG_SCROLL = {
  /** Tempo de atenuação da inércia em segundos (padrão: 0.85s - mais rápido e ágil). */
  duracaoSegundos: 0.85,
  /** Multiplicador de pixels por giro da rodinha do mouse (padrão: 1.35 - avança mais pixels). */
  multiplicadorRoda: 1.35,
  /** Sensibilidade para trackpads/touch (padrão: 1.8). */
  multiplicadorTouch: 1.8,
} as const;

/**
 * Provedor de rolagem suave inercial contínua (Lenis) para a Landing Page.
 *
 * Transforma a experiência de rolagem da página inteira, aplicando desaceleração
 * inercial física e amortecimento a cada movimento da rodinha do mouse ou do trackpad:
 * - Elimina os saltos mecânicos e truncados nativos do navegador.
 * - Sincroniza um loop contínuo de interpolação via `requestAnimationFrame`.
 * - Fornece suporte a touchpads e telas de alta taxa de atualização (120Hz/ProMotion).
 * - Registra a instância ativa em `window.__lenis` para que ações de navegação por âncora
 *   possam reutilizar o mesmo motor de interpolação.
 * - Desativa o bypass automático por flag de SO (`respectReducedMotion: false`) para
 *   garantir que a rolagem fluida e elegante seja sempre entregue aos usuários.
 *
 * @param props - Propriedades contendo os filhos React a serem renderizados.
 *
 * @example
 * ```tsx
 * <SmoothScrollProvider>
 *   <LandingHeader />
 *   <main>{conteudo}</main>
 * </SmoothScrollProvider>
 * ```
 */
export function SmoothScrollProvider({ children }: SmoothScrollProviderProps) {
  useEffect(() => {
    // Não inicializar no servidor ou em ambientes de testes sem navegador completo (ex: JSDOM)
    if (
      typeof window === "undefined" ||
      typeof Window === "undefined" ||
      typeof window.matchMedia !== "function" ||
      process.env.NODE_ENV === "test"
    ) {
      return;
    }

    const lenis = new Lenis({
      duration: CONFIG_SCROLL.duracaoSegundos,
      wheelMultiplier: CONFIG_SCROLL.multiplicadorRoda,
      touchMultiplier: CONFIG_SCROLL.multiplicadorTouch,
      easing: (t: number) => Math.min(1, 1.001 - Math.pow(2, -10 * t)),
      orientation: "vertical",
      gestureOrientation: "vertical",
      smoothWheel: true,
      respectReducedMotion: false,
    });

    window.__lenis = lenis;

    let rafId: number;
    const onRaf = (time: number) => {
      lenis.raf(time);
      rafId = requestAnimationFrame(onRaf);
    };
    rafId = requestAnimationFrame(onRaf);

    return () => {
      cancelAnimationFrame(rafId);
      lenis.destroy();
      delete window.__lenis;
    };
  }, []);

  return <>{children}</>;
}

