"use client";

import { useState, useRef, useEffect, useCallback } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { toast } from "sonner";
import {
  ChevronDown,
  Gift,
  LogOut,
  Ticket,
  User,
  ShieldCheck,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { useUserAuth } from "@/hooks/useUserAuth";
import { mascaraWhatsApp } from "@/lib/constants";
import { cn } from "@/lib/utils";

/**
 * Ações de conta exibidas no cabeçalho da Landing Page.
 *
 * - Visitante:
 *   - Botão "Entrar" (link para /login).
 *   - Botão "Criar Conta" (link para /cadastro com destaque esmeralda).
 *
 * - Cliente autenticado:
 *   1. Botão "Minhas Reservas" com destaque ao lado de "Agendar Agora".
 *   2. Menu de usuário refinado com avatar generoso, nome, subtítulo "Minha Conta"
 *      e dropdown interativo com acesso rápido ao perfil, fidelidade e logout.
 *
 * @example
 * <AcoesUsuarioHeader />
 */
export function AcoesUsuarioHeader() {
  const { user, logout } = useUserAuth();
  const router = useRouter();
  const [menuAberto, setMenuAberto] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);

  // Fecha o menu suspenso ao clicar fora do componente ou pressionar Escape
  useEffect(() => {
    if (!menuAberto) return;

    const handleClickFora = (event: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
        setMenuAberto(false);
      }
    };

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        setMenuAberto(false);
      }
    };

    document.addEventListener("mousedown", handleClickFora);
    document.addEventListener("keydown", handleKeyDown);
    return () => {
      document.removeEventListener("mousedown", handleClickFora);
      document.removeEventListener("keydown", handleKeyDown);
    };
  }, [menuAberto]);

  const handleLogout = useCallback(async () => {
    setMenuAberto(false);
    try {
      await logout();
      toast.success("Você saiu da sua conta com sucesso.");
      router.push("/");
    } catch {
      toast.error("Erro ao encerrar a sessão.");
