                    <Gift className="w-4 h-4" />
                  </div>
                  <div className="flex flex-col">
                    <span className="font-semibold text-white">Programa de Fidelidade</span>
                    <span className="text-[10px] text-slate-400">Cartela de carimbos e recompensas</span>
                  </div>
                </Link>

                <Link
                  href="/minha-conta"
                  role="menuitem"
                  onClick={() => setMenuAberto(false)}
                  className="flex items-center gap-3 px-3 py-2 rounded-xl text-xs font-medium text-slate-200 hover:text-white hover:bg-slate-800/80 transition-colors group"
                >
                  <div className="w-7 h-7 rounded-lg bg-slate-800 text-slate-300 flex items-center justify-center flex-shrink-0 group-hover:text-white transition-colors">
