                  </div>
                </Link>
              </div>

              {/* Separador e Logout */}
              <div className="pt-1 mt-1 border-t border-slate-800/80">
                <button
                  type="button"
                  role="menuitem"
                  onClick={handleLogout}
                  className="w-full flex items-center gap-3 px-3 py-2 rounded-xl text-xs font-semibold text-red-400 hover:text-red-300 hover:bg-red-500/10 transition-colors text-left cursor-pointer group"
