          )}
        </div>
      </div>
    );
  }

  return (
    <div className="flex items-center gap-2">
      <Link href="/login" id="header-entrar">
        <Button
          size="sm"
          variant="ghost"
          className="text-slate-300 hover:text-white text-xs font-semibold px-3 py-1 cursor-pointer"
