import React from "react";
import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
import { render, screen, fireEvent, waitFor } from "@testing-library/react";
import { AcoesUsuarioHeader } from "@/components/landing/AcoesUsuarioHeader";

// Mock do next/link
vi.mock("next/link", () => ({
  default: ({ href, children, ...rest }: { href: string; children: React.ReactNode }) => (
    <a href={href} {...rest}>
      {children}
    </a>
  ),
}));

// Mock do sonner toast
vi.mock("sonner", () => ({
  toast: {
    success: vi.fn(),
    error: vi.fn(),
  },
}));

let mockUser: { id: string; nome: string; telefone: string } | null = null;
const mockLogout = vi.fn().mockResolvedValue(undefined);

vi.mock("@/hooks/useUserAuth", () => ({
  useUserAuth: () => ({
    user: mockUser,
    logout: mockLogout,
    isAutenticado: Boolean(mockUser),
  }),
}));

describe("AcoesUsuarioHeader - Componente", () => {
  beforeEach(() => {
    mockUser = null;
    vi.clearAllMocks();
  });

  afterEach(() => {
    vi.restoreAllMocks();
  });

  it("renderiza botoes Entrar e Criar Conta quando visitante nao autenticado", () => {
    render(<AcoesUsuarioHeader />);

    expect(screen.getByText("Entrar")).toBeInTheDocument();
    expect(screen.getByText("Criar Conta")).toBeInTheDocument();
    expect(document.getElementById("header-entrar")).toHaveAttribute("href", "/login");
    expect(document.getElementById("header-criar-conta")).toHaveAttribute("href", "/cadastro");
    expect(screen.queryByText("Minhas Reservas")).not.toBeInTheDocument();
  });

  it("renderiza botao de Minhas Reservas e identificador do usuario quando autenticado", () => {
    mockUser = { id: "u1", nome: "Rafaella Silva", telefone: "11987654321" };
    render(<AcoesUsuarioHeader />);

    // Botão de Minhas Reservas destacado
    const linkReservas = document.getElementById("header-minha-conta");
    expect(linkReservas).toBeInTheDocument();
    expect(linkReservas).toHaveAttribute("href", "/minha-conta");
    expect(screen.getByText("Minhas Reservas")).toBeInTheDocument();

    // Trigger do perfil do usuário
    expect(screen.getByText("Rafaella")).toBeInTheDocument();
    expect(screen.getByText("R")).toBeInTheDocument();
    expect(screen.getByText("Minha Conta")).toBeInTheDocument();
  });

  it("abre o menu dropdown ao clicar no botao do perfil e fecha ao clicar fora", async () => {
    mockUser = { id: "u1", nome: "Rafaella Silva", telefone: "11987654321" };
    render(
      <div>
        <div data-testid="fora">Elemento externo</div>
        <AcoesUsuarioHeader />
      </div>
    );

    const triggerBtn = document.getElementById("header-usuario-menu-btn");
    expect(triggerBtn).toBeInTheDocument();
    expect(triggerBtn).toHaveAttribute("aria-expanded", "false");

    // Abre menu
    fireEvent.click(triggerBtn!);
    expect(triggerBtn).toHaveAttribute("aria-expanded", "true");

    // Verifica itens dentro do card suspenso
    expect(screen.getByText("Rafaella Silva")).toBeInTheDocument();
    expect(screen.getByText("(11) 98765-4321")).toBeInTheDocument();
    expect(screen.getByText("Programa de Fidelidade")).toBeInTheDocument();
    expect(screen.getByText("Meu Perfil e Cadastro")).toBeInTheDocument();
    expect(screen.getByText("Sair da Conta")).toBeInTheDocument();

    // Clica fora para fechar
    fireEvent.mouseDown(screen.getByTestId("fora"));
    await waitFor(() => {
      expect(triggerBtn).toHaveAttribute("aria-expanded", "false");
    });
  });

  it("fecha o menu dropdown ao pressionar a tecla Escape", async () => {
    mockUser = { id: "u1", nome: "Rafaella Silva", telefone: "11987654321" };
    render(<AcoesUsuarioHeader />);

    const triggerBtn = document.getElementById("header-usuario-menu-btn");
    fireEvent.click(triggerBtn!);
    expect(triggerBtn).toHaveAttribute("aria-expanded", "true");

    fireEvent.keyDown(document, { key: "Escape" });
    await waitFor(() => {
      expect(triggerBtn).toHaveAttribute("aria-expanded", "false");
    });
  });

  it("executa logout ao clicar em Sair da Conta", async () => {
    mockUser = { id: "u1", nome: "Rafaella Silva", telefone: "11987654321" };
    render(<AcoesUsuarioHeader />);

    const triggerBtn = document.getElementById("header-usuario-menu-btn");
    fireEvent.click(triggerBtn!);

    const btnLogout = screen.getByText("Sair da Conta");
    fireEvent.click(btnLogout);

    await waitFor(() => {
      expect(mockLogout).toHaveBeenCalledTimes(1);
    });
  });
});

