"use client";

import { useEffect, useCallback } from "react";
import type { UserProfile } from "@/lib/supabase/types";
import {
  cadastrarUsuarioSupabase,
  loginUsuarioSupabase,
  obterUsuarioAtual,
  logoutUsuarioSupabase,
  atualizarPerfilSupabase,
  excluirContaSupabase,
} from "@/lib/supabase/authService";
import { supabase, isSupabaseConfigured } from "@/lib/supabase/client";
import { useAuthStore, getUsuarioCacheLocal } from "@/store/useAuthStore";

/**
 * Hook de autenticação do usuário.
 *
 * Conectado à store global Zustand (`useAuthStore`) com hidratação síncrona
 * de cache local (`localStorage`), garantindo que:
 * 1. A sessão nunca se perca durante navegações de rota (ex.: ir para /minha-conta e voltar para /).
 * 2. Não ocorra flickering de botões de login/cadastro enquanto a sessão é revalidada em segundo plano.
 * 3. Qualquer alteração de perfil reflita simultaneamente em todos os componentes.
 */
export function useUserAuth() {
  const user = useAuthStore((s) => s.user);
  const loading = useAuthStore((s) => s.loading);
  const setUser = useAuthStore((s) => s.setUser);
  const setLoading = useAuthStore((s) => s.setLoading);

  // Carrega e sincroniza usuário na inicialização
  useEffect(() => {
    let isMounted = true;

    // Hidratação síncrona do cache se a store ainda estiver nula
    if (!user && typeof window !== "undefined") {
      const cached = getUsuarioCacheLocal();
      if (cached && isMounted) {
        setUser(cached);
      }
    }

    async function carregarSessao() {
      try {
        const u = await obterUsuarioAtual();
        if (u && u.id.startsWith("usr_demo_")) {
          await logoutUsuarioSupabase();
          if (isMounted) {
            setUser(null);
            setLoading(false);
          }
          return;
        }
        if (isMounted) {
          setUser(u);
          setLoading(false);
        }
      } catch {
        if (isMounted) setLoading(false);
      }
    }

    void carregarSessao();

    const handleSync = async () => {
      if (!isMounted) return;
      try {
        const u = await obterUsuarioAtual();
        if (isMounted) setUser(u);
      } catch {}
    };

    if (typeof window !== "undefined") {
      window.addEventListener("storage", handleSync);
      window.addEventListener("focus", handleSync);
    }

    // Inscrição para mudanças de autenticação no Supabase
    let authSub: { unsubscribe: () => void } | null = null;
    if (isSupabaseConfigured()) {
      const {
        data: { subscription },
      } = supabase.auth.onAuthStateChange(async (_event, session) => {
        if (!isMounted) return;
        const u = await obterUsuarioAtual();
        if (isMounted) setUser(u);
      });
      authSub = subscription;
    }

    return () => {
      isMounted = false;
      if (typeof window !== "undefined") {
        window.removeEventListener("storage", handleSync);
        window.removeEventListener("focus", handleSync);
      }
      if (authSub) {
        authSub.unsubscribe();
      }
    };
  }, [setUser, setLoading, user]);

  const login = useCallback(
    async (telefone: string, senha: string): Promise<{ success: boolean; error?: string }> => {
      setLoading(true);
      const res = await loginUsuarioSupabase(telefone, senha);
      setLoading(false);
      if (res.user) {
        setUser(res.user);
        return { success: true };
      }
      return { success: false, error: res.error || "Erro ao realizar login." };
    },
    [setUser, setLoading]
  );

  const cadastrar = useCallback(
    async (
      nome: string,
      telefone: string,
      senha: string,
      dataNascimento?: string
    ): Promise<{ success: boolean; user?: UserProfile; error?: string }> => {
      setLoading(true);
      const res = await cadastrarUsuarioSupabase(nome, telefone, senha, dataNascimento);
      setLoading(false);
      if (res.user) {
        setUser(res.user);
        return { success: true, user: res.user };
      }
      return { success: false, error: res.error || "Erro ao cadastrar usuário." };
    },
    [setUser, setLoading]
  );

  const logout = useCallback(async () => {
    setLoading(true);
    await logoutUsuarioSupabase();
    setUser(null);
    setLoading(false);
  }, [setUser, setLoading]);

  const atualizarPerfil = useCallback(
    async (dados: Partial<Omit<UserProfile, "id" | "criadoEm">>): Promise<boolean> => {
      if (!user) return false;
      const updated = await atualizarPerfilSupabase(user.id, dados);
      if (updated) {
        setUser(updated);
        return true;
      }
      return false;
    },
    [user, setUser]
  );

  const excluirConta = useCallback(async (): Promise<boolean> => {
    if (!user) return false;
    const ok = await excluirContaSupabase(user.id);
    if (ok) {
      setUser(null);
      return true;
    }
    return false;
  }, [user, setUser]);

  return {
    user,
    loading,
    isAutenticado: Boolean(user),
    login,
    cadastrar,
    logout,
    atualizarPerfil,
    excluirConta,
  };
}

"use client";

import Link from "next/link";
import { Ticket } from "lucide-react";
import { useUserAuth } from "@/hooks/useUserAuth";

/**
 * Ações de conta exibidas no cabeçalho da Landing Page.
 *
 * Todos os botões compartilham rigorosamente a mesma altura (`h-9` / 36px),
 * raio arredondado (`rounded-full`) e alinhamento vertical.
 *
 * - Estado carregando inicial:
 *   - Esqueleto discreto com `h-9` para evitar o efeito de piscar (flicker)
 *     botões de visitante quando o usuário já está autenticado.
 *
 * - Visitante:
 *   - Botão "Entrar" (link para /login).
 *   - Botão "Criar Conta" (link para /cadastro).
 *
 * - Cliente autenticado:
 *   1. Botão destacado de "Minhas Reservas" com ícone de Ticket (link para /minha-conta).
 *   2. Pílula de perfil com avatar e primeiro nome que leva diretamente para a página de perfil (/minha-conta).
 *
 * @example
 * <AcoesUsuarioHeader />
 */
export function AcoesUsuarioHeader() {
  const { user, loading } = useUserAuth();

  // Se a verificação inicial de autenticação estiver ocorrendo e não houver usuário em cache,
  // exibe um marcador sutil de mesma altura (h-9) para não piscar "Entrar/Criar Conta" indevidamente.
  if (loading && !user) {
    return (
      <div
        data-testid="header-auth-loading"
        className="h-9 w-20 rounded-full bg-slate-800/30 border border-slate-700/30 animate-pulse"
        aria-hidden="true"
      />
    );
  }

  if (user) {
    const primeiroNome = user.nome.split(" ")[0];
    const inicial = user.nome.charAt(0).toUpperCase();

    return (
      <div className="flex items-center gap-2 sm:gap-2.5">
        {/* ── Botão Destacado: Minhas Reservas (ao lado de Agendar Agora) ── */}
        <Link href="/minha-conta" id="header-minha-conta">
          <button
            type="button"
            className="inline-flex items-center gap-2 h-9 px-4 rounded-full border border-slate-700 hover:border-emerald-500/50 bg-slate-900/90 hover:bg-slate-800 text-slate-200 hover:text-white text-xs font-semibold transition-all shadow-sm cursor-pointer focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-emerald-500/50"
          >
            <Ticket className="w-3.5 h-3.5 text-emerald-400" aria-hidden="true" />
            <span>Minhas Reservas</span>
          </button>
        </Link>

        {/* ── Botão Perfil do Usuário: Link direto para a página de perfil ── */}
        <Link
          href="/minha-conta"
          id="header-usuario-perfil"
          aria-label={`Ver perfil de ${user.nome}`}
        >
          <button
            type="button"
            className="inline-flex items-center gap-2.5 h-9 pl-1.5 pr-3.5 rounded-full border border-slate-700/80 hover:border-emerald-500/50 bg-slate-900/80 hover:bg-slate-800/90 text-slate-200 hover:text-white transition-all shadow-sm cursor-pointer group focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-emerald-500/50"
          >
            <div className="w-6 h-6 rounded-full bg-gradient-to-br from-emerald-500/25 via-emerald-600/20 to-teal-700/30 border border-emerald-500/40 text-emerald-300 flex items-center justify-center font-bold text-xs shadow-inner flex-shrink-0">
              {inicial}
            </div>
            <span className="text-xs font-semibold text-white group-hover:text-emerald-300 transition-colors max-w-[120px] truncate">
              {primeiroNome}
            </span>
          </button>
        </Link>
      </div>
    );
  }

  return (
    <div className="flex items-center gap-2">
      <Link href="/login" id="header-entrar">
        <button
          type="button"
          className="inline-flex items-center justify-center h-9 px-3.5 rounded-full text-slate-300 hover:text-white text-xs font-semibold hover:bg-slate-800/60 transition-colors cursor-pointer focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-emerald-500/50"
        >
          Entrar
        </button>
      </Link>
      <Link href="/cadastro" id="header-criar-conta">
        <button
          type="button"
