            Escolinhas da LP ({escolinhas.length})
          </button>
        </div>
      </div>

      {/* ── ABA 1: GALERIA DE FOTOS ────────────────────────────────────────── */}
      {abaAtiva === "galeria" && (
        <div className="space-y-4">
