/**
 * @module hooks/useInstitucionalService
 *
 * Hook React para gerenciar os dados da galeria de fotos da estrutura
 * e das escolinhas esportivas, integrando leitura, criação, edição,
 * exclusão, upload de imagens, filtros de categoria e sincronização
 * bidirecional com os contratos de escolinhas da agenda.
 */

"use client";

import { useState, useEffect, useCallback, useMemo } from "react";
import type {
  GaleriaItem,
  EscolinhaItem,
  FiltroCategoriaGaleria,
  CriarGaleriaInput,
  AtualizarGaleriaInput,
  CriarEscolinhaInput,
  AtualizarEscolinhaInput,
} from "@/lib/institucional/types";
import {
  filtrarGaleria,
  filtrarEscolinhas,
  sincronizarEscolinhasComContratos,
} from "@/lib/institucional/institucionalHelpers";
import {
  listarGaleria,
  criarGaleriaItem,
  atualizarGaleriaItem,
  excluirGaleriaItem,
  listarEscolinhas,
  criarEscolinha,
  atualizarEscolinha,
  excluirEscolinha,
  uploadImagemInstitucional,
} from "@/lib/supabase/institucionalRepository";
import { GALERIA_INICIAL, ESCOLINHAS_INICIAIS } from "@/lib/institucional/dadosIniciais";
import { useContratosService } from "@/hooks/useContratosService";

export function useInstitucionalService() {
  const [galeria, setGaleria] = useState<GaleriaItem[]>([...GALERIA_INICIAL]);
  const [escolinhas, setEscolinhas] = useState<EscolinhaItem[]>([...ESCOLINHAS_INICIAIS]);
  const [carregando, setCarregando] = useState(true);
  const [filtroCategoria, setFiltroCategoria] = useState<FiltroCategoriaGaleria>("todas");

  // Acesso aos contratos de escolinhas cadastrados na aba Escolinhas da agenda
  const { getContratosPorTipo } = useContratosService();
  const contratosEscolinhas = useMemo(
    () => getContratosPorTipo("escolinha"),
    [getContratosPorTipo]
  );

  const recarregar = useCallback(async () => {
    try {
      const [itensGaleria, itensEscolinhas] = await Promise.all([
        listarGaleria(),
        listarEscolinhas(),
      ]);
      setGaleria(itensGaleria);

      // Sincroniza com as escolinhas existentes na agenda (se houver contratos)
      if (contratosEscolinhas.length > 0) {
        const sincronizadas = sincronizarEscolinhasComContratos(
          itensEscolinhas,
          contratosEscolinhas
        );
        setEscolinhas(sincronizadas);
      } else {
        setEscolinhas(itensEscolinhas);
      }
    } catch {
      // Fallback gracioso mantendo os itens iniciais
    } finally {
      setCarregando(false);
    }
  }, [contratosEscolinhas]);

  useEffect(() => {
    void recarregar();
  }, [recarregar]);

  // Lista pública de fotos filtradas por categoria (apenas ativas)
  const galeriaFiltrada = useMemo(() => {
    return filtrarGaleria(galeria, filtroCategoria, true);
  }, [galeria, filtroCategoria]);

  // Lista pública de escolinhas (apenas ativas)
  const escolinhasAtivas = useMemo(() => {
    return filtrarEscolinhas(escolinhas, true);
  }, [escolinhas]);

  // Sincronização manual acionável pelo admin
  const sincronizarComContratos = useCallback(async () => {
    if (contratosEscolinhas.length === 0) {
      return { totalSincronizadas: 0 };
    }
    const sincronizadas = sincronizarEscolinhasComContratos(
      escolinhas,
      contratosEscolinhas
    );
    setEscolinhas(sincronizadas);
    for (const esc of sincronizadas) {
      await atualizarEscolinha(esc.id, esc);
    }
    return { totalSincronizadas: contratosEscolinhas.length };
  }, [escolinhas, contratosEscolinhas]);

  // Ações de gerenciamento da galeria
  const criarFoto = useCallback(async (input: CriarGaleriaInput) => {
    const criada = await criarGaleriaItem(input);
    setGaleria((prev) => [...prev, criada]);
    return criada;
  }, []);

  const atualizarFoto = useCallback(
    async (id: string, input: AtualizarGaleriaInput) => {
      const atualizada = await atualizarGaleriaItem(id, input);
      if (atualizada) {
        setGaleria((prev) => prev.map((item) => (item.id === id ? atualizada : item)));
      }
      return atualizada;
    },
    []
  );

  const removerFoto = useCallback(async (id: string) => {
    const ok = await excluirGaleriaItem(id);
    if (ok) {
      setGaleria((prev) => prev.filter((item) => item.id !== id));
    }
    return ok;
  }, []);

  // Ações de gerenciamento das escolinhas
  const criarNovaEscolinha = useCallback(async (input: CriarEscolinhaInput) => {
    const criada = await criarEscolinha(input);
    setEscolinhas((prev) => [...prev, criada]);
    return criada;
  }, []);

  const atualizarEscolinhaExistente = useCallback(
    async (id: string, input: AtualizarEscolinhaInput) => {
      const atualizada = await atualizarEscolinha(id, input);
      if (atualizada) {
        setEscolinhas((prev) => prev.map((item) => (item.id === id ? atualizada : item)));
      }
      return atualizada;
    },
    []
  );

  const removerEscolinhaExistente = useCallback(async (id: string) => {
    const ok = await excluirEscolinha(id);
    if (ok) {
      setEscolinhas((prev) => prev.filter((item) => item.id !== id));
    }
    return ok;
  }, []);

  return {
    galeria,
    escolinhas,
    galeriaFiltrada,
    escolinhasAtivas,
    contratosEscolinhas,
    carregando,
    filtroCategoria,
    setFiltroCategoria,
    recarregar,
    sincronizarComContratos,
    criarFoto,
    atualizarFoto,
    removerFoto,
    criarNovaEscolinha,
    atualizarEscolinhaExistente,
    removerEscolinhaExistente,
    fazerUploadImagem: uploadImagemInstitucional,
  };
}

