const criarNovaEscolinha = useCallback(
  async (input: CriarEscolinhaInput) => {
    const esporteInferido = input.sportName.toLowerCase().includes("beach")
      ? "beach_tennis"
      : input.sportName.toLowerCase().includes("futebol")
      ? "futebol"
      : "tenis";

    const res = await criarContrato({
